// Источник: web-тест .qa/e2e/tests/nusach-switch/ns-01-menu-mobile.spec.ts, план .qa/e2e/specs/nusach-switch.md, кейс .qa/tests/nusach-switch/NS-01-menu.md
// Тикет #6a86f7d8 «פיתוח: החלפת נוסח בתוך התפילה». Опора: F-37 AC1, AC4 · S-33 AC5 · Figma 612-867.
// ОБНОВЛЕНО 21.10 (#32e3cd9a, עבר QA): в меню ровно 2 пункта «אשכנזי» / «ספרדי» (по показанному тексту, Figma S-33), «עדות המזרח · בקרוב» нет.
// Ширины 360/390 из web — это ширина экрана телефона, на котором идёт прогон (viewport в приложении не задаётся).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel, tapText, expectVisibleText } from '../../helpers/ui.ts';
import { openPrayer } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

/** Тап по точке экрана (клик «мимо меню»). */
async function tapAt(x: number, y: number) {
  await driver.action('pointer', { parameters: { pointerType: 'touch' } })
    .move({ x: Math.round(x), y: Math.round(y) })
    .down().pause(60).up().perform();
}

describe('Смена нусаха внутри молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('NS-01 Меню смены нусаха — только список, активный отмечен, карточка в пределах экрана #6a86f7d8 #32e3cd9a @prod-safe', async () => {
    // 1. Открыть מנחה (נוסח профиля — אשכנז).
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await expectVisibleText('מנחה (אשכנזי)');

    // 2. Нажать стрелку у «מנחה (אשכנזי)» — список нусахов, активный отмечен ✓, ровно 2 пункта, «עדות המזרח»/«בקרוב» нет (#32e3cd9a).
    await (await byLabel('בחירת נוסח. הנוסח המוצג: אשכנזי')).click();
    await expectVisibleText('אשכנזי');
    await expectVisibleText('✓');
    await expectVisibleText('ספרדי');
    await expect(byTextContains('עדות המזרח')).not.toBeExisting();
    await expect(byTextContains('בקרוב')).not.toBeExisting();

    // Нет текста-пояснения внизу меню и баннера над молитвой.
    await expect(byTextContains('הבחירה חלה')).not.toBeDisplayed();
    await expect(byTextContains('ההעדפה')).not.toBeDisplayed();

    // Пункты меню полностью в пределах экрана (getLocation/getSize — в тех же единицах, что getWindowSize).
    const { width, height } = await driver.getWindowSize();
    for (const item of ['אשכנזי', 'ספרדי']) {
      const el = await byText(item);
      const { x, y } = await el.getLocation();
      const size = await el.getSize();
      expect(x).toBeGreaterThanOrEqual(0);
      expect(y).toBeGreaterThanOrEqual(0);
      expect(x + size.width).toBeLessThanOrEqual(width);
      expect(y + size.height).toBeLessThanOrEqual(height);
    }

    // 3. Нажать «אשכנזי» (уже выбран) — диалога нет, אשכנזי по-прежнему отмечен (пункта «עדות המזרח» больше нет, #32e3cd9a).
    await tapText('אשכנזי');
    await expectVisibleText('מנחה (אשכנזי)');
    await expectVisibleText('✓');
    await expect(byTextContains('להחליף את התפילה לנוסח')).not.toBeDisplayed();

    // 4. Тап мимо меню (низ экрана, по центру) — меню закрыто, заголовок прежний.
    await tapAt(width / 2, height - 20);
    await expect(byText('ספרדי')).not.toBeDisplayed();
    await expectVisibleText('מנחה (אשכנזי)');
  });
});
